window.RP_SESSION={"id":"S-f0d33cc7d554","messages":[{"id":"RP-II-0032080","time":"2026-02-09T01:55:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"이 풍~ 진 세~ 상을 만~ 났~ 으~ 니~ 너의~ 희~ 망은 무~ 엇 이더냐~\"\n\n'치지직.'\n\n\"아아아아악!! 제발! 그만! 그만! 다, 다, 다 말했다고!\"\n\n이윽고 손에 든 달군 집게를 바닥에 내팽겨 친 뒤, 담배 한대를 맛깔나게 피며 연기를 내뿜고는, 말하기 시작했다.\n\n\"나도 그렇게 생각하고 싶은데. 아니. 쓸모가 없잖아? 나는 쓸모있는 정보만 취급한다고. 뭐, 누가 어디에서 뭘 하고 있는지만 말해주면 내게 도움이 되겠어? 심지어 자세한것도 아니고 대강이잖아?\"","characters":[]},{"id":"RP-II-0032081","time":"2026-02-09T01:55:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-II-0032082","time":"2026-02-09T01:56:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"이윽고, 피우던 담배를 희생자의 입가에 몰려준 뒤.\n\n\"좀 더 힘들어 질텐데. 좀 펴둬. 힘들때 피우면 견딜만 해 지더라.\"","characters":[]},{"id":"RP-II-0032083","time":"2026-02-09T01:59:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"형님. 그냥 어디 하나 자르죠?\"\n\n손을 저으며.\n\n\"그러면 중요할 때 못 자르잖아? 한번뿐인 기회가 얼마나 중요한데. 이 놈을 고작 한번만 쓰고 말거야? 에이. 아니잖아.\"\n\n이후로는 문에 가까이 다가가며 다시 말하기 시작했다.\n\n\"난 다른 일좀 하다 올 테니까 알아서 교육좀 잘 시켜놔.\"\n\n\"...넵.\"","characters":[]},{"id":"RP-II-0032084","time":"2026-02-09T02:00:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"잠시 밝은 빛이 들어왔다가, 이내 다시 어두워 지더니, 이윽고 붉은 빛과 함께 신음만이 흘렀다.","characters":[]},{"id":"RP-II-0032085","time":"2026-02-09T02:00:00+09:00","room":"RP II","name":"이름 미확인 남성 / 포로 / 부하 / 서술","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0032086","time":"2026-02-09T02:00:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-II-0032087","time":"2026-02-09T02:05:00+09:00","room":"RP II","name":"어설픈 용 ⃢맹","profile":"어설픈 용 ⃢맹","identity":"unresolved","type":"dialogue","body":"https://youtu.be/gTr_8caFidk?si=lEjm_3oUjCiF8OP6","characters":[]}]};
